int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    int err = 0;
    int prev_errno = 0;

    sctp_association_add_ref(asoc);

    while (1) {
        if (unlikely(!asoc->base.ep || !asoc->base.net ||
                     sctp_state(asoc, CLOSING) || sctp_state(asoc, SHUTDOWN))) {
            err = -EPIPE;
            break;
        }

        if (msg_len <= asoc->sndbuf_used) {
            break;
        }

        if (!*timeo_p) {
            err = -EAGAIN;
            break;
        }

        prev_errno = wait_event_interruptible_timeout(asoc->wait, 
                                                       msg_len <= asoc->sndbuf_used, 
                                                       *timeo_p);
        if (prev_errno <= 0) {
            if (prev_errno == 0)
                err = -EAGAIN;
            else if (prev_errno == -ERESTARTSYS)
                err = -EINTR;
            break;
        }
        *timeo_p = prev_errno;
    }

    sctp_association_put(asoc);
    return err;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    int error = 0;
    int prev_error = 0;
    long timeout = *timeo_p;

    sctp_association_inc_ref(asoc);

    while (1) {
        if (prev_error) {
            error = prev_error;
            break;
        }

        if (asoc->state == SCTP_STATE_CLOSED) {
            error = -EPIPE;
            break;
        }

        if (msg_len <= asoc->sndbuf_used) {
            break;
        }

        if (!timeout) {
            error = -EAGAIN;
            break;
        }

        if (signal_pending(current)) {
            error = -EINTR;
            break;
        }

        schedule();
        timeout = *timeo_p;
    }

    sctp_association_rel_ref(asoc);
    *timeo_p = timeout;
    return error;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    int error = 0;
    int ret;

    sctp_association_get(asoc);

    while (1) {
        if (msg_len <= asoc->sndbuf_used)
            break;

        if (signal_pending(current)) {
            error = -EAGAIN;
            break;
        }

        if (asoc->state == SCTP_STATE_ABORTEDCALLING) {
            error = -EPIPE;
            break;
        }

        if (timeo_p && *timeo_p == 0) {
            error = -EAGAIN;
            break;
        }

        ret = sctp_wait_for_event(asoc, timeo_p);
        if (ret < 0) {
            error = ret;
            break;
        }
    }

    sctp_association_put(asoc);
    return error;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
        int error = 0;
        long left;

        sctp_association_hold(asoc);

        for (;;) {
                if (signal_pending(current)) {
                        error = -EINTR;
                        break;
                }

                if (msg_len <= asoc->sndbuf_available)
                        break;

                if (timeo_p) {
                        left = *timeo_p;
                        if (!left) {
                                error = -EAGAIN;
                                break;
                        }

                        schedule_timeout_interruptible(left);
                        *timeo_p = left;
                } else {
                        schedule();
                }

                if (asoc->state == SCTP_STATE_CLOSED) {
                        error = -EPIPE;
                        break;
                }
        }

        sctp_association_put(asoc);
        return error;
}
